{
  "packet_id": "H6-T03-3",
  "claim_id": "C006",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C006.component",
    "value": "Which orders actually required approval must first be verified.",
    "scope": "Applicability of the internal approval requirement to the orders being examined.",
    "provenance": {
      "refs": [
        {
          "source_id": "P004",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P004 explicitly makes verification of which orders required approval a preliminary requirement."
    }
  },
  "signal_basis": {
    "component_id": "C006.signal_basis",
    "value": "The operation checks order-level evidence of authorized approval before placement and compares attachment frequency among comparable covered orders. The proposed signal is fewer missing attachments after responsibility becomes explicit, repeated across comparable periods if volume permits.",
    "scope": "Determining approval applicability before interpreting order-level approval evidence or attachment frequencies for covered orders.",
    "provenance": {
      "refs": [
        {
          "source_id": "P001",
          "role": "CONTEXT"
        },
        {
          "source_id": "P005",
          "role": "SUPPORT"
        },
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans identify the examined orders, the approval-evidence check, the restriction to comparable covered orders, and the proposed attachment signal with its repetition qualifier."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C006.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The procedural claim is supported without an additional unresolved empirical relation."
    }
  },
  "rationale": "Approval applicability determines which orders can be assessed against the rule and included in the covered-order comparison. Verifying that applicability is therefore licensed as a preliminary procedural requirement. The observed attachment signal does not itself determine which orders were subject to approval.",
  "uncertainty": "The packet does not resolve individual orders' applicability, but that does not undermine the requirement to verify it.",
  "anomalies": []
}
